    def get_pos_tag(self, sentence):
        """
        Remove punctuations of the sentence and tokenizes the input sentence, mark the part of speech tag of each word.
        :param sentence: a sentence str
        :return: list, part of speech tag of each word in the sentence.
        """
        punctuations = set()
        punctuations.add('!')
        punctuations.add('?')
        punctuations.add('&')
        punctuations.add('*')
        punctuations.add('(')
        punctuations.add(')')
        punctuations.add('_')
        punctuations.add('{')
        punctuations.add('}')
        tokens = word_tokenize(sentence)
        pos_tags = []
        for token in tokens:
            if token in punctuations:
                continue
            if token.isdigit():
                pos_tags.append('NN')
            elif token.isalpha():
                if pos_tag.count(token) == 0:
                    pos_tag = pos_tag.index(token) + 1
                elif token == '!':
                    pos_tag = 1
                elif token == '?':
                    pos_tag = 2
                elif token == '&':
                    pos_tag = 3
                elif token == '*':
                    pos_tag = 4
                elif token == '(':
                    pos_tag = 5
                elif token == ')':
                    pos_tag = 6
                elif token in pos_tags:
                    pos_tag = pos_tags.index(token) + 1
            elif token in pos_tags:
                pos_tags.append(token)
            else:
                pos_tags.append(token)
        return pos_tags
